// Explicit, bounded texture import. A prepared batch is a value: preparing,
// cancelling or failing cannot mutate the source files or a CAD document.
import CoreGraphics
import Foundation
import ImageIO

nonisolated enum CADTextureImport {
    static let maximumSourceBytes = 64 * 1024 * 1024
    static let maximumBatchSourceBytes = 128 * 1024 * 1024
    static let maximumSourcePixels = 64 * 1024 * 1024
    // Match the existing viewport's resident resource ceiling. Include mip
    // levels here, rather than equating a compressed PNG with its GPU cost.
    static let maximumResidentBytes = 64 * 1024 * 1024
    static let maximumResidentResources = 64

    struct Source: Identifiable, Equatable, Sendable {
        let id: UUID
        let name: String
        let bytes: Data

        init(id: UUID = UUID(), name: String, bytes: Data) {
            self.id = id
            self.name = String(name.prefix(120))
            self.bytes = bytes
        }
    }

    struct Descriptor: Equatable, Sendable {
        let width: Int
        let height: Int
        let depth: Int
        let exifOrientation: Int
        let hasAlpha: Bool
        let colorModel: String
        let profile: String
        let encodedBytes: Int
        let canKeepOriginal: Bool

        var orientedWidth: Int { (5...8).contains(exifOrientation) ? height : width }
        var orientedHeight: Int { (5...8).contains(exifOrientation) ? width : height }
    }

    enum Choice: String, CaseIterable, Sendable {
        case choose, original, png4096, png2048, png1024, png512

        var maximumDimension: Int? {
            switch self {
            case .choose, .original: return nil
            case .png4096: return 4096
            case .png2048: return 2048
            case .png1024: return 1024
            case .png512: return 512
            }
        }
    }

    struct Selection: Equatable, Sendable {
        var source: Source
        var slot: MaterialTextureSlot
        var choice: Choice
    }

    struct Review: Identifiable, Sendable {
        let id: UUID
        let sources: [Source]
        let descriptors: [Descriptor]
        let startingSlot: MaterialTextureSlot
    }

    struct Budget: Equatable, Sendable {
        let resourceCount: Int
        let decodedBytes: Int
        let residentBytes: Int
        /// Conservative working-set estimate: retained encoded input/output
        /// plus one sequential decode, normalization and read-back bitmap.
        let workingBytes: Int

        var fits: Bool {
            residentBytes <= maximumResidentBytes && resourceCount <= maximumResidentResources
        }
    }

    struct Receipt: Equatable, Sendable, Identifiable {
        let id: UUID
        let sourceName: String
        let sourceSHA256: String
        let outputSHA256: String
        let slot: MaterialTextureSlot
        let converted: Bool
        let width: Int
        let height: Int
        let byteCount: Int
        /// Generated by decoding the final encoded bytes, never from the
        /// source bitmap. This is the image the review UI actually displays.
        let readBackPreviewPNG: Data
    }

    struct Prepared: Equatable, Sendable {
        let textures: [CADMaterialTexture]
        let receipts: [Receipt]
        let budget: Budget
    }

    enum Failure: Error, LocalizedError, Equatable {
        case sourceTooLarge, invalidImage, unsupportedHDR, multipleImages
        case chooseConversion, originalNeedsConversion, duplicateSlots
        case memoryBudget, encodingTooLarge, conversionFailed, staleImport

        var errorDescription: String? {
            switch self {
            case .sourceTooLarge:
                return FloeCADStrings.text("cad.textureImport.error.sourceSize", "Choose up to six images, each at most 64 MB and 128 MB in total.")
            case .invalidImage:
                return FloeCADStrings.text("cad.textureImport.error.invalid", "This image could not be read safely. The source and existing textures are unchanged.")
            case .unsupportedHDR:
                return FloeCADStrings.text("cad.textureImport.error.hdr", "Convert HDR, EXR, KTX or UDIM resources to individual SDR images first. The originals are unchanged.")
            case .multipleImages:
                return FloeCADStrings.text("cad.textureImport.error.multiple", "Choose a single-frame image. Pages and animation frames will not be discarded.")
            case .chooseConversion, .originalNeedsConversion:
                return FloeCADStrings.text("cad.textureImport.error.choice", "Choose a PNG conversion size for images that cannot be kept as they are.")
            case .duplicateSlots:
                return FloeCADStrings.text("cad.textureImport.error.slots", "Choose a different texture channel for each image.")
            case .memoryBudget:
                return FloeCADStrings.text("cad.textureImport.error.budget", "These textures exceed the 64 MB image memory budget. Choose smaller conversion sizes or remove unused maps.")
            case .encodingTooLarge:
                return FloeCADStrings.text("cad.textureImport.error.encoded", "The converted PNG is larger than 8 MB. Choose a smaller size; no texture has been replaced.")
            case .conversionFailed:
                return FloeCADStrings.text("cad.textureImport.error.convert", "The image could not be converted and read back. No texture has been replaced.")
            case .staleImport:
                return FloeCADStrings.text("cad.textureImport.error.stale", "The material changed during import. Choose the images again to keep your latest edits.")
            }
        }
    }

    /// Header-only inspection. Do not allocate a bitmap to decide whether an
    /// image needs conversion. Multi-page/animated sources are never truncated.
    static func inspect(_ data: Data) throws -> Descriptor {
        guard !data.isEmpty, data.count <= maximumSourceBytes else { throw Failure.sourceTooLarge }
        guard let source = CGImageSourceCreateWithData(data as CFData,
                [kCGImageSourceShouldCache: false] as CFDictionary),
              let type = CGImageSourceGetType(source) as String? else { throw Failure.invalidImage }
        let lowered = type.lowercased()
        guard !lowered.contains("exr"), !lowered.contains("radiance"),
              !lowered.contains("hdr"), !lowered.contains("ktx") else { throw Failure.unsupportedHDR }
        guard CGImageSourceGetCount(source) == 1 else { throw Failure.multipleImages }
        guard CGImageSourceGetStatus(source) == .statusComplete,
              CGImageSourceGetStatusAtIndex(source, 0) == .statusComplete else { throw Failure.invalidImage }
        guard let properties = CGImageSourceCopyPropertiesAtIndex(source, 0, nil) as? [CFString: Any],
              let width = (properties[kCGImagePropertyPixelWidth] as? NSNumber)?.intValue,
              let height = (properties[kCGImagePropertyPixelHeight] as? NSNumber)?.intValue,
              width > 0, height > 0, width <= 16384, height <= 16384,
              width <= maximumSourcePixels / height else { throw Failure.invalidImage }
        let depth = (properties[kCGImagePropertyDepth] as? NSNumber)?.intValue ?? 8
        guard depth > 0, depth <= 16 else { throw Failure.unsupportedHDR }
        let orientation = (properties[kCGImagePropertyOrientation] as? NSNumber)?.intValue ?? 1
        guard (1...8).contains(orientation) else { throw Failure.invalidImage }
        let model = properties[kCGImagePropertyColorModel] as? String ?? ""
        let profile = properties[kCGImagePropertyProfileName] as? String ?? ""
        let lowerProfile = profile.lowercased()
        guard !lowerProfile.contains("2100"), !lowerProfile.contains("pq"),
              !lowerProfile.contains("hlg") else { throw Failure.unsupportedHDR }
        let alpha = (properties[kCGImagePropertyHasAlpha] as? NSNumber)?.boolValue ?? false
        let keep = MaterialImageSniffer.mimeType(of: data) != nil
            && data.count <= CADMaterialLimits.maximumTextureBytes
            && width <= CADImagePackingLimits.maximumDimension
            && height <= CADImagePackingLimits.maximumDimension
            && depth <= 8 && orientation == 1
            && (model == "RGB" || model == "Gray")
        return Descriptor(width: width, height: height, depth: depth,
                          exifOrientation: orientation, hasAlpha: alpha,
                          colorModel: model, profile: profile,
                          encodedBytes: data.count, canKeepOriginal: keep)
    }

    static func validateSources(_ sources: [Source]) throws -> [Descriptor] {
        guard !sources.isEmpty, sources.count <= MaterialTextureSlot.allCases.count,
              sources.reduce(0, { $0 + $1.bytes.count }) <= maximumBatchSourceBytes else {
            throw Failure.sourceTooLarge
        }
        return try sources.map { try inspect($0.bytes) }
    }

    /// User-selected files are copied with a bounded read. No path is retained
    /// in the document; security scope is released even on failure/cancellation.
    static func readFiles(_ urls: [URL]) throws -> [Source] {
        guard !urls.isEmpty, urls.count <= MaterialTextureSlot.allCases.count else { throw Failure.sourceTooLarge }
        var sources: [Source] = []
        var total = 0
        for url in urls {
            try Task.checkCancellation()
            let scoped = url.startAccessingSecurityScopedResource()
            defer { if scoped { url.stopAccessingSecurityScopedResource() } }
            let attributes = try url.resourceValues(forKeys: [.fileSizeKey, .isRegularFileKey])
            guard attributes.isRegularFile == true,
                  let size = attributes.fileSize, size > 0, size <= maximumSourceBytes,
                  size <= maximumBatchSourceBytes - total else { throw Failure.sourceTooLarge }
            let file = try FileHandle(forReadingFrom: url)
            defer { try? file.close() }
            var bytes = Data()
            while let chunk = try file.read(upToCount: 256 * 1024), !chunk.isEmpty {
                try Task.checkCancellation()
                guard chunk.count <= maximumSourceBytes - bytes.count,
                      chunk.count <= maximumBatchSourceBytes - total - bytes.count else { throw Failure.sourceTooLarge }
                bytes.append(chunk)
            }
            _ = try inspect(bytes)
            total += bytes.count
            sources.append(Source(name: url.lastPathComponent, bytes: bytes))
        }
        return sources
    }

    static func outputSize(_ descriptor: Descriptor, choice: Choice) throws -> (width: Int, height: Int) {
        switch choice {
        case .choose: throw Failure.chooseConversion
        case .original:
            guard descriptor.canKeepOriginal else { throw Failure.originalNeedsConversion }
            return (descriptor.width, descriptor.height)
        default:
            guard let maximum = choice.maximumDimension else { throw Failure.chooseConversion }
            let scale = min(1, Double(maximum) / Double(max(descriptor.orientedWidth, descriptor.orientedHeight)))
            // Round upwards for preflight; the actual decoded dimensions are
            // measured again before a batch can be accepted.
            return (max(1, Int(ceil(Double(descriptor.orientedWidth) * scale))),
                    max(1, Int(ceil(Double(descriptor.orientedHeight) * scale))))
        }
    }

    static func mipmappedBytes(width: Int, height: Int) -> Int {
        var width = width, height = height, bytes = 0
        repeat {
            bytes += width * height * 4
            if width == 1 && height == 1 { break }
            width = max(1, width / 2); height = max(1, height / 2)
        } while true
        return bytes
    }

    static func budget(_ selections: [Selection], existing: [CADMaterialTexture]) throws -> Budget {
        _ = try validateSources(selections.map(\.source))
        guard Set(selections.map(\.slot)).count == selections.count else { throw Failure.duplicateSlots }
        var seen = Set<String>()
        var decoded = 0, resident = 0, count = 0, encoded = 0, largest = 0
        func include(key: String, width: Int, height: Int, byteCount: Int) {
            guard seen.insert(key).inserted else { return }
            let pixels = width * height * 4
            decoded += pixels
            resident += mipmappedBytes(width: width, height: height)
            count += 1; encoded += byteCount; largest = max(largest, pixels)
        }
        for texture in existing {
            let descriptor = try inspect(texture.bytes)
            guard descriptor.canKeepOriginal else { throw Failure.invalidImage }
            include(key: resourceKey(texture), width: descriptor.width, height: descriptor.height,
                    byteCount: texture.bytes.count)
        }
        for selection in selections {
            let descriptor = try inspect(selection.source.bytes)
            let size = try outputSize(descriptor, choice: selection.choice)
            let texture = CADMaterialTexture(slot: selection.slot, bytes: selection.source.bytes)
            let key = resourceKey(texture) + (selection.choice == .original ? "" : "|\(selection.choice.rawValue)")
            include(key: key, width: size.width, height: size.height,
                    byteCount: selection.choice == .original ? selection.source.bytes.count : CADMaterialLimits.maximumTextureBytes)
        }
        return Budget(resourceCount: count, decodedBytes: decoded, residentBytes: resident,
                      workingBytes: selections.reduce(0, { $0 + $1.source.bytes.count }) + encoded + largest * 3)
    }

    static func actualBudget(_ textures: [CADMaterialTexture], existing: [CADMaterialTexture]) throws -> Budget {
        let selections = textures.map {
            Selection(source: Source(name: $0.name, bytes: $0.bytes), slot: $0.slot, choice: .original)
        }
        return try budget(selections, existing: existing)
    }

    /// One bitmap at a time. Cancellation is checked around every expensive
    /// codec operation; no converted bytes escape on a failed/cancelled batch.
    static func prepare(_ selections: [Selection], existing: [CADMaterialTexture]) throws -> Prepared {
        try Task.checkCancellation()
        let predicted = try budget(selections, existing: existing)
        guard predicted.fits else { throw Failure.memoryBudget }
        var textures: [CADMaterialTexture] = []
        var receipts: [Receipt] = []
        for selection in selections {
            try Task.checkCancellation()
            let pair: (CADMaterialTexture, Receipt) = try autoreleasepool {
                let output: Data
                if selection.choice == .original {
                    output = selection.source.bytes
                } else {
                    output = try convert(selection)
                }
                try Task.checkCancellation()
                guard output.count <= CADMaterialLimits.maximumTextureBytes else { throw Failure.encodingTooLarge }
                let descriptor = try inspect(output)
                guard descriptor.canKeepOriginal,
                      case .success = CADExportImage.decode(output),
                      let preview = previewPNG(output) else { throw Failure.conversionFailed }
                let texture = CADMaterialTexture(slot: selection.slot, name: selection.source.name, bytes: output)
                let receipt = Receipt(id: selection.source.id, sourceName: selection.source.name,
                    sourceSHA256: CADMaterialTexture.digest(selection.source.bytes), outputSHA256: texture.sha256,
                    slot: selection.slot, converted: selection.choice != .original,
                    width: descriptor.width, height: descriptor.height, byteCount: output.count,
                    readBackPreviewPNG: preview)
                return (texture, receipt)
            }
            textures.append(pair.0); receipts.append(pair.1)
        }
        try Task.checkCancellation()
        let measured = try actualBudget(textures, existing: existing)
        guard measured.fits else { throw Failure.memoryBudget }
        let resultBudget = Budget(resourceCount: measured.resourceCount, decodedBytes: measured.decodedBytes,
            residentBytes: measured.residentBytes, workingBytes: max(predicted.workingBytes, measured.workingBytes))
        return Prepared(textures: textures, receipts: receipts, budget: resultBudget)
    }

    static func prepareAsync(_ selections: [Selection], existing: [CADMaterialTexture]) async throws -> Prepared {
        try Task.checkCancellation()
        let work = Task.detached(priority: .userInitiated) { try prepare(selections, existing: existing) }
        let prepared = try await withTaskCancellationHandler(operation: { try await work.value }, onCancel: { work.cancel() })
        try Task.checkCancellation()
        return prepared
    }

    private static func resourceKey(_ texture: CADMaterialTexture) -> String {
        // Include origin for RealityKit and slot/colour interpretation for
        // Metal. A shared blob in different semantic slots is not one upload.
        "\(texture.slot.rawValue)|\(texture.colorSpace.rawValue)|\(texture.orientation.rawValue)|\(CADMaterialTexture.digest(texture.bytes))"
    }

    private static func convert(_ selection: Selection) throws -> Data {
        let descriptor = try inspect(selection.source.bytes)
        let size = try outputSize(descriptor, choice: selection.choice)
        guard let source = CGImageSourceCreateWithData(selection.source.bytes as CFData,
                [kCGImageSourceShouldCache: false] as CFDictionary),
              let image = CGImageSourceCreateThumbnailAtIndex(source, 0, [
                kCGImageSourceCreateThumbnailFromImageAlways: true,
                kCGImageSourceCreateThumbnailWithTransform: true,
                kCGImageSourceThumbnailMaxPixelSize: max(size.width, size.height),
                kCGImageSourceShouldAllowFloat: false,
                kCGImageSourceShouldCacheImmediately: true,
              ] as CFDictionary), image.width > 0, image.height > 0,
              image.width <= size.width, image.height <= size.height,
              let srgb = CGColorSpace(name: CGColorSpace.sRGB) else { throw Failure.conversionFailed }
        try Task.checkCancellation()
        let isColor = selection.slot == .baseColor || selection.slot == .emissive
        // Colour maps are colour-managed into sRGB. For data maps, assign a
        // linear profile (without changing samples) and expand gray to RGB in
        // that same linear space. Re-tag the final PNG as sRGB below so an
        // embedded ICC profile cannot apply an extra transfer to data values.
        let workingSpace: CGColorSpace
        let input: CGImage?
        if isColor {
            workingSpace = srgb
            input = image
        } else {
            guard let linearRGB = CGColorSpace(name: CGColorSpace.linearSRGB),
                  let linearGray = CGColorSpace(name: CGColorSpace.linearGray) else { throw Failure.conversionFailed }
            workingSpace = linearRGB
            switch image.colorSpace?.numberOfComponents {
            case 3: input = image.copy(colorSpace: linearRGB)
            case 1: input = image.copy(colorSpace: linearGray)
            default: throw Failure.conversionFailed
            }
        }
        guard let input,
              let context = CGContext(data: nil, width: image.width, height: image.height,
                bitsPerComponent: 8, bytesPerRow: image.width * 4, space: workingSpace,
                bitmapInfo: CGImageAlphaInfo.premultipliedLast.rawValue) else { throw Failure.conversionFailed }
        context.setBlendMode(.copy)
        context.interpolationQuality = .none
        context.draw(input, in: CGRect(x: 0, y: 0, width: image.width, height: image.height))
        guard let normalized = context.makeImage()?.copy(colorSpace: srgb) else { throw Failure.conversionFailed }
        return try encodePNG(normalized)
    }

    private static func previewPNG(_ bytes: Data) -> Data? {
        guard let source = CGImageSourceCreateWithData(bytes as CFData,
                [kCGImageSourceShouldCache: false] as CFDictionary),
              let image = CGImageSourceCreateThumbnailAtIndex(source, 0, [
                kCGImageSourceCreateThumbnailFromImageAlways: true,
                kCGImageSourceThumbnailMaxPixelSize: 256,
                kCGImageSourceShouldCacheImmediately: true,
              ] as CFDictionary) else { return nil }
        return try? encodePNG(image)
    }

    private static func encodePNG(_ image: CGImage) throws -> Data {
        try Task.checkCancellation()
        let bytes = NSMutableData()
        guard let destination = CGImageDestinationCreateWithData(bytes as CFMutableData,
                "public.png" as CFString, 1, nil) else { throw Failure.conversionFailed }
        CGImageDestinationAddImage(destination, image, [kCGImagePropertyOrientation: 1] as CFDictionary)
        guard CGImageDestinationFinalize(destination) else { throw Failure.conversionFailed }
        try Task.checkCancellation()
        return bytes as Data
    }
}
